fn days_to_next_sunday(day: &str) -> i8 {
    // Map each valid abbreviation to an index where SUN=0, ..., SAT=6.
    let idx: i8 = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => unreachable!("Input is guaranteed to be a valid day abbreviation"),
    };

    // Days until next Sunday; Sunday itself should yield 7, not 0.
    let diff = (7 - idx) % 7;
    if diff == 0 { 7 } else { diff }
}

fn main() {
    // Example usage
    assert_eq!(days_to_next_sunday("SUN"), 7);
    assert_eq!(days_to_next_sunday("MON"), 6);
    assert_eq!(days_to_next_sunday("SAT"), 1);
}